CREATE OR REPLACE FUNCTION public.adopt_client_program(p_program_id uuid, p_client_id uuid, p_name text DEFAULT NULL) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$ DECLARE v_uid uuid := auth.uid(); v_fork_id uuid; v_day record; v_new_day_id uuid; BEGIN IF v_uid IS NULL THEN RAISE EXCEPTION 'Not authenticated'; END IF; IF NOT public.is_coach_of(p_client_id) THEN RAISE EXCEPTION 'Not your client'; END IF; IF NOT EXISTS (SELECT 1 FROM public.programs p JOIN public.program_assignments pa ON pa.program_id = p.id WHERE p.id = p_program_id AND pa.client_id = p_client_id) THEN RAISE EXCEPTION 'Program not assigned to this client'; END IF; INSERT INTO public.programs (owner_id, name, description, duration_weeks) SELECT v_uid, COALESCE(NULLIF(btrim(p_name), ''), p.name || ' (repris)'), COALESCE(p.description, ''), p.duration_weeks FROM public.programs p WHERE p.id = p_program_id RETURNING id INTO v_fork_id; FOR v_day IN SELECT * FROM public.program_days WHERE program_id = p_program_id ORDER BY order_index LOOP INSERT INTO public.program_days (program_id, weekday, name, routine_id, order_index) VALUES (v_fork_id, v_day.weekday, v_day.name, v_day.routine_id, v_day.order_index) RETURNING id INTO v_new_day_id; INSERT INTO public.program_day_exercises (program_day_id, name, default_sets, default_reps, default_reps_min, default_rir, default_rest_seconds, default_weight_kg, order_index) SELECT v_new_day_id, name, default_sets, default_reps, default_reps_min, default_rir, default_rest_seconds, default_weight_kg, order_index FROM public.program_day_exercises WHERE program_day_id = v_day.id ORDER BY order_index; END LOOP; PERFORM public.snapshot_program_revision(v_fork_id); RETURN v_fork_id; END; $$;
